const profile = $json || {};
const EXPECTED_ACCOUNT_ID = String($('Report Inputs').first().json.expectedJiraAccountId || '').trim();
const EXPECTED_TIME_ZONE = String($('Report Inputs').first().json.reportTimezone || 'Etc/UTC').trim();

if (!EXPECTED_ACCOUNT_ID || EXPECTED_ACCOUNT_ID.startsWith('REPLACE_')) {
  throw new Error('Configure expectedJiraAccountId in the Report Inputs node first.');
}
if (!profile.active) {
  throw new Error('The Jira reporting account is inactive.');
}
if (String(profile.accountId || '') !== EXPECTED_ACCOUNT_ID) {
  throw new Error('The Jira credential/profile does not match the approved reporting account.');
}
if (String(profile.timeZone || '') !== EXPECTED_TIME_ZONE) {
  throw new Error(`Jira timezone mismatch: expected ${EXPECTED_TIME_ZONE}, received ${profile.timeZone || 'missing'}.`);
}

return {
  json: {
    ...profile,
    timezoneVerified: true,
    verifiedTimeZone: EXPECTED_TIME_ZONE
  }
};

const pages = $input.all().map((item) => item.json || {});
  const identity = $('Get Jira Identity').first().json || {};
  const inputs = $('Report Inputs').first().json || {};
  const names = {};
  const issuesByKey = new Map();

  for (const page of pages) {
    Object.assign(names, page.names || {});
    for (const issue of (Array.isArray(page.issues) ? page.issues : [])) {
      if (issue && issue.key) issuesByKey.set(issue.key, issue);
    }
  }

  const severityFieldIds = Object.entries(names)
    .filter(([id, label]) => id.startsWith('customfield_') && /severity/i.test(String(label || '')))
    .sort((a, b) => {
      const aExact = String(a[1]).trim().toLowerCase() === 'severity' ? 0 : 1;
      const bExact = String(b[1]).trim().toLowerCase() === 'severity' ? 0 : 1;
      return aExact - bExact || a[0].localeCompare(b[0]);
    })
    .map(([id]) => id);

  const common = {
    jiraIdentity: {
      accountId: identity.accountId || '',
      displayName: identity.displayName || '',
      emailAddress: identity.emailAddress || '',
      active: identity.active === true
    },
    additionalActivities: String(inputs.additionalActivities || '').trim(),
    blockers: String(inputs.blockers || '').trim(),
    tomorrowPlan: String(inputs.tomorrowPlan || '').trim(),
    severityFieldIds,
    fieldNames: names
  };

  const issues = [...issuesByKey.values()];
  if (issues.length === 0) {
    return [{ json: { ...common, empty: true, key: '', issue: null } }];
  }

  return issues.map((issue) => ({
    json: {
      ...common,
      empty: false,
      key: issue.key,
      issue
    }
  }));

const sourceItems = $('Prepare Issues for Changelog').all().map((item) => item.json || {});
  const responseItems = $input.all();
  const changelogByKey = new Map();

  function pairedIndex(item, fallbackIndex) {
    const link = item.pairedItem;
    if (Array.isArray(link) && link.length) return Number(link[0]?.item);
    if (link && typeof link === 'object' && link.item !== undefined) return Number(link.item);
    if (sourceItems.length === responseItems.length) return fallbackIndex;
    if (sourceItems.length === 1) return 0;
    return NaN;
  }

  for (let i = 0; i < responseItems.length; i++) {
    const responseItem = responseItems[i];
    const body = responseItem.json?.body ?? responseItem.json ?? {};
    let index = pairedIndex(responseItem, i);
    let source = Number.isInteger(index) ? sourceItems[index] : undefined;

    if (!source || (!source.empty && !source.key)) {
      const selfUrl = String(body.self || '');
      const match = selfUrl.match(/\/issue\/([^/]+)\/changelog/i);
      if (match) source = sourceItems.find((candidate) => candidate.key === decodeURIComponent(match[1]));
    }

    if (!source) {
      throw new Error('Unable to associate a Jira changelog page with its source issue.');
    }
    if (source.empty) continue;

    const values = Array.isArray(body.values) ? body.values : [];
    if (!changelogByKey.has(source.key)) changelogByKey.set(source.key, []);
    changelogByKey.get(source.key).push(...values);
  }

  const base = sourceItems[0] || {};
  const identity = base.jiraIdentity || {};
  if (!identity.accountId) {
    throw new Error('Jira identity response is missing accountId; deterministic creator and transition checks cannot continue.');
  }

  const TIME_ZONE = String($('Report Inputs').first().json.reportTimezone || 'Etc/UTC').trim();
  const now = new Date();

  function localDateKey(value) {
    const date = value instanceof Date ? value : new Date(value);
    if (Number.isNaN(date.getTime())) return '';
    const parts = new Intl.DateTimeFormat('en-GB', {
      timeZone: TIME_ZONE,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit'
    }).formatToParts(date);
    const get = (type) => parts.find((part) => part.type === type)?.value || '';
    return `${get('year')}-${get('month')}-${get('day')}`;
  }

  const reportDateKey = localDateKey(now);
  const reportDate = new Intl.DateTimeFormat('en-GB', {
    timeZone: TIME_ZONE,
    day: '2-digit',
    month: 'short',
    year: 'numeric'
  }).format(now);

  function adfText(node) {
    if (!node) return '';
    if (typeof node === 'string') return node;
    if (Array.isArray(node)) return node.map(adfText).filter(Boolean).join('\n');
    if (node.type === 'text') return String(node.text || '');
    if (node.type === 'hardBreak') return '\n';
    const content = Array.isArray(node.content) ? node.content : [];
    const joined = content.map(adfText).filter(Boolean).join(node.type === 'paragraph' ? '' : '\n');
    return joined.trim();
  }

  function fieldLabel(value) {
    if (value === null || value === undefined || value === '') return '';
    if (Array.isArray(value)) return value.map(fieldLabel).filter(Boolean).join(', ');
    if (typeof value === 'object') {
      return String(value.value ?? value.name ?? value.displayName ?? value.label ?? '').trim();
    }
    return String(value).trim();
  }

  function importance(fields, severityFieldIds) {
    for (const fieldId of severityFieldIds || []) {
      const label = fieldLabel(fields[fieldId]);
      if (label) return { type: 'Severity', value: label };
    }
    const priority = fieldLabel(fields.priority);
    return priority ? { type: 'Priority', value: priority } : null;
  }

  function ticket(issue, category) {
    const fields = issue.fields || {};
    const imp = importance(fields, base.severityFieldIds || []);
    return {
      key: String(issue.key || ''),
      summary: String(fields.summary || ''),
      category,
      status: String(fields.status?.name || ''),
      created: String(fields.created || ''),
      updated: String(fields.updated || ''),
      creatorAccountId: String(fields.creator?.accountId || ''),
      description: adfText(fields.description),
      ...(imp ? { importanceType: imp.type, importance: imp.value } : {})
    };
  }

  const created = [];
  const resolved = [];
  const reopened = [];
  const issueMap = new Map(
    sourceItems
      .filter((item) => !item.empty && item.issue?.key)
      .map((item) => [item.issue.key, item.issue])
  );

  const sourceFacts = [...issueMap.values()]
    .map((issue) => {
      const fact = ticket(issue, 'retrieved');
      return {
        key: fact.key,
        summary: fact.summary,
        status: fact.status,
        created: fact.created,
        updated: fact.updated,
        creatorAccountId: fact.creatorAccountId,
        ...(fact.importance ? { importanceType: fact.importanceType, importance: fact.importance } : {})
      };
    })
    .sort((a, b) => a.key.localeCompare(b.key));

  for (const issue of issueMap.values()) {
    const fields = issue.fields || {};
    const key = issue.key;
    if (
      localDateKey(fields.created) === reportDateKey &&
      String(fields.creator?.accountId || '') === String(identity.accountId)
    ) {
      created.push(ticket(issue, 'created'));
    }

    let hasResolved = false;
    let hasReopened = false;
    for (const history of (changelogByKey.get(key) || [])) {
      if (localDateKey(history.created) !== reportDateKey) continue;
      if (String(history.author?.accountId || '') !== String(identity.accountId)) continue;
      for (const change of (Array.isArray(history.items) ? history.items : [])) {
        if (String(change.field || '').toLowerCase() !== 'status') continue;
        const from = String(change.fromString || '').trim().toLowerCase();
        const to = String(change.toString || '').trim().toLowerCase();
        if (from === 'in qa' && to === 'resolved') hasResolved = true;
        if (from === 'in qa' && to === 're open') hasReopened = true;
      }
    }
    if (hasResolved) resolved.push(ticket(issue, 'resolved'));
    if (hasReopened) reopened.push(ticket(issue, 'reopened'));
  }

  function dedupe(items) {
    return [...new Map(items.map((item) => [item.key, item])).values()]
      .sort((a, b) => a.key.localeCompare(b.key));
  }

  const categories = {
    created: dedupe(created),
    resolved: dedupe(resolved),
    reopened: dedupe(reopened)
  };

  const newIssueStatusBreakdown = {};
  for (const item of categories.created) {
    const status = item.status || 'Unknown';
    newIssueStatusBreakdown[status] = (newIssueStatusBreakdown[status] || 0) + 1;
  }
  const orderedBreakdown = Object.fromEntries(
    Object.entries(newIssueStatusBreakdown).sort(([a], [b]) => a.localeCompare(b))
  );

  const counts = {
    newIssues: categories.created.length,
    resolved: categories.resolved.length,
    reopened: categories.reopened.length,
    newIssuesByStatus: orderedBreakdown
  };

  const additionalActivities = String(base.additionalActivities || '').trim();
  const blockers = String(base.blockers || '').trim();
  const tomorrowPlan = String(base.tomorrowPlan || '').trim();

  const immutableEvidence = {
    reportDate,
    timezone: TIME_ZONE,
    counts,
    tickets: categories,
    additionalActivities: additionalActivities || null,
    blockers: blockers || null,
    tomorrowPlan: tomorrowPlan || null
  };

  const prompt = [
    'Return JSON only with exactly these properties: "summary", "mainFocus", "activities", "blockers", and "nextSteps".',
    '"summary" and "mainFocus" must be non-empty professional English strings.',
    '"activities" and "nextSteps" must be arrays of concise professional English strings. "blockers" must be one concise English string.',
    'Translate Roman Urdu or mixed-language input into natural professional English. Correct spelling, grammar, and typing mistakes.',
    'Split distinct activities and next actions into separate array items. Preserve the meaning and do not omit useful facts.',
    'Use only the immutable evidence below. Never invent activities, results, people, tickets, counts, fixes, or plans.',
    'Do not calculate or alter Jira ticket IDs, summaries, classifications, statuses, severity/priority, or numeric counts; those are rendered deterministically outside Gemini.',
    'If the user explicitly says there is no blocker, set "blockers" to exactly "None." even when they mention pending work or a dependency. Put that dependency in "summary" or "nextSteps" instead.',
    'Include explicit follow-ups mentioned anywhere in the form input, such as a planned discussion, in "nextSteps".',
    'Never include Jira issue keys or numeric ticket counts in generated fields; those are rendered separately.',
    'Preserve concrete examples and important technical details such as features, environments, and planned follow-up dates.',
    'When blockers is "None.", do not call pending work blocked; state neutrally that it could not be retested until the code is pushed.',
    'Infer obvious typing corrections from context. For example, Postman "futre/further validation" means further validation, not future validation.',
    'Do not copy rough input verbatim. Rewrite it clearly and concisely.',
    'IMMUTABLE EVIDENCE:',
    JSON.stringify(immutableEvidence)
  ].join('\n');

  return [{
    json: {
      reportDate,
      timezone: TIME_ZONE,
      reportDateKey,
      jiraIdentity: identity,
      counts,
      categories,
      retrievedIssueKeys: sourceFacts.map((fact) => fact.key),
      sourceFacts,
      additionalActivities,
      blockers,
      tomorrowPlan,
      prompt
    }
  }];

function decodeBytes(bytes) {
  if (!Array.isArray(bytes)) return '';
  return new TextDecoder('utf-8').decode(Uint8Array.from(bytes));
}

function parseJsonText(value, label) {
  const text = String(value ?? '').replace(/^\uFEFF/, '').trim();
  if (!text) throw new Error(`${label} was empty.`);
  const cleaned = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  try {
    return JSON.parse(cleaned);
  } catch (error) {
    throw new Error(`${label} was not valid JSON: ${error.message}`);
  }
}

function normalizeCandidate(value, label) {
  if (value === null || value === undefined) return null;
  if (typeof value === 'string') return parseJsonText(value, label);
  if (Array.isArray(value)) return parseJsonText(decodeBytes(value), label);
  if (typeof value !== 'object') return null;
  if (value.type === 'Buffer' && Array.isArray(value.data)) {
    return parseJsonText(decodeBytes(value.data), label);
  }
  return value;
}

function responseEnvelope(value) {
  const root = normalizeCandidate(value, 'Gemini response');
  const candidates = [
    root,
    root?.body,
    root?.data,
    root?.response,
    root?.result,
    root?.geminiResponse
  ];

  for (let index = 0; index < candidates.length; index++) {
    const candidate = normalizeCandidate(candidates[index], `Gemini response variant ${index + 1}`);
    if (!candidate || typeof candidate !== 'object') continue;
    if (candidate.error) {
      const message = candidate.error.message || candidate.error.status || JSON.stringify(candidate.error);
      throw new Error(`Gemini API error: ${message}`);
    }
    if (Array.isArray(candidate.candidates)) return candidate;
    if (typeof candidate.summary === 'string' && typeof candidate.mainFocus === 'string') {
      return { directStructuredOutput: candidate };
    }
  }

  const keys = root && typeof root === 'object' ? Object.keys(root).join(', ') : typeof root;
  throw new Error(`Gemini response did not contain a supported JSON envelope. Received: ${keys || 'no fields'}.`);
}

let responseValue = $json;
if ($binary?.geminiResponseFile) {
  try {
    const responseBuffer = await this.helpers.getBinaryDataBuffer(0, 'geminiResponseFile');
    responseValue = responseBuffer.toString('utf8');
  } catch (error) {
    throw new Error(`Gemini binary response could not be read: ${error.message}`);
  }
}

let envelope;
try {
  envelope = responseEnvelope(responseValue);
} catch (error) {
  throw new Error(`Gemini response envelope could not be parsed: ${error.message}`);
}

if (envelope.promptFeedback?.blockReason) {
  throw new Error(`Gemini blocked the request: ${envelope.promptFeedback.blockReason}.`);
}

  const direct = envelope.directStructuredOutput;
  const raw = direct
    ? JSON.stringify(direct)
    : envelope?.candidates?.[0]?.content?.parts?.map((part) => part?.text || '').join('').trim();

  if (!raw) {
    const finishReason = envelope?.candidates?.[0]?.finishReason || 'unknown';
    throw new Error(`Gemini returned no report content (finish reason: ${finishReason}).`);
  }

  let parsed;
  try {
    parsed = direct || parseJsonText(raw, 'Gemini generated content');
  } catch (error) {
    throw new Error(`Gemini output was not valid JSON: ${error.message}`);
  }

  if (!parsed || typeof parsed.summary !== 'string' || !parsed.summary.trim()) {
    throw new Error('Gemini output is missing a non-empty summary.');
  }
  if (typeof parsed.mainFocus !== 'string' || !parsed.mainFocus.trim()) {
    throw new Error('Gemini output is missing a non-empty mainFocus.');
  }
  if (!Array.isArray(parsed.activities) || !parsed.activities.every((item) => typeof item === 'string')) {
    throw new Error('Gemini output activities must be an array of strings.');
  }
  if (typeof parsed.blockers !== 'string' || !parsed.blockers.trim()) {
    throw new Error('Gemini output is missing blockers.');
  }
  if (!Array.isArray(parsed.nextSteps) || !parsed.nextSteps.every((item) => typeof item === 'string')) {
    throw new Error('Gemini output nextSteps must be an array of strings.');
  }

  function cleanList(values) {
    return [...new Set(values.map((value) => String(value || '').trim()).filter(Boolean))];
  }

  const polishedActivities = cleanList(parsed.activities);
  const polishedNextSteps = cleanList(parsed.nextSteps);
  const polishedBlockers = parsed.blockers.trim();

  const data = $('Classify Jira Activity & Prepare Gemini').first().json;
  const counts = data.counts;
  const categories = data.categories;

  function displayStatus(value) {
    return String(value || 'Unknown')
      .split(/\s+/)
      .map((word) => word ? word.charAt(0).toUpperCase() + word.slice(1).toLowerCase() : '')
      .join(' ');
  }

  function ticketLine(item) {
    const importance = item.importance ? ` | ${item.importanceType}: ${item.importance}` : '';
    if (item.category === 'resolved') {
      return `• ${item.key} - ${item.summary}${importance} | Result: Resolved`;
    }
    if (item.category === 'reopened') {
      return `• ${item.key} - ${item.summary}${importance} | Result: Reopened`;
    }
    return `• ${item.key} - ${item.summary}${importance} | Status: ${displayStatus(item.status)}`;
  }

  function section(title, items) {
    const lines = items.length ? items.map(ticketLine) : ['• None.'];
    return [`*${title}:*`, ...lines].join('\n');
  }

  const breakdown = Object.entries(counts.newIssuesByStatus || {});
  const breakdownText = breakdown.length
    ? ` (${breakdown.map(([status, count]) => `${displayStatus(status)}: ${count}`).join(', ')})`
    : '';

  const summaryLines = [
    '*Summary:*',
    `• New issues / improvements reported: ${counts.newIssues}${breakdownText}.`,
    `• QA verified / resolved: ${counts.resolved}.`,
    `• Reopened: ${counts.reopened}.`,
    ...polishedActivities.map((activity) => `• ${activity}`),
    `• ${parsed.summary.trim()}`,
    `• Main Focus: ${parsed.mainFocus.trim()}`
  ];

  const parts = [
    `*QA Daily Report - ${data.reportDate}*`,
    summaryLines.join('\n'),
    section('QA Verified / Resolved', categories.resolved),
    section('New Issues / Improvements Reported', categories.created)
  ];

  if (categories.reopened.length) {
    parts.push(section('Reopened Issues', categories.reopened));
  }

  parts.push(`*Blockers:*\n${polishedBlockers}`);
  const nextText = polishedNextSteps.length
    ? polishedNextSteps.map((step) => `• ${step}`).join('\n')
    : '• No plan was provided.';
  parts.push(`*Next:*\n${nextText}`);

  const report = parts.join('\n\n');
  const required = [
    `*QA Daily Report - ${data.reportDate}*`,
    '*Summary:*',
    '*QA Verified / Resolved:*',
    '*New Issues / Improvements Reported:*',
    '*Blockers:*',
    '*Next:*'
  ];
  for (const heading of required) {
    if (!report.includes(heading)) throw new Error(`Final report validation failed: missing ${heading}`);
  }

  return [{
    json: {
      report,
      reportDate: data.reportDate,
      timezone: data.timezone,
      counts,
      categories,
      retrievedIssueKeys: data.retrievedIssueKeys,
      sourceFacts: data.sourceFacts,
      jiraIdentity: data.jiraIdentity,
      geminiSummary: parsed.summary.trim(),
      geminiMainFocus: parsed.mainFocus.trim(),
      polishedActivities,
      polishedBlockers,
      polishedNextSteps,
      slackDispatchEnabled: true
    }
  }];
